const applyFirstInsuranceSurcharge = (amount: number): number =>
  (amount * (100 + FIRST_INSURANCE_SURCHARGE_PERCENT)) / 100;

const roundInMhpcoFavor = (premium: number): number => Math.ceil(premium);

export const quote = (
  customer: Customer,
  items: Item[],
  contractIndex: number,
): number => {
  const base = items.reduce((sum, item) => sum + basePremium(item), 0);
  return roundInMhpcoFavor(applyFirstInsuranceSurcharge(base) + PROCESSING_FEE);
};
